int Ans[maxn],cnt;
int main(){
    ios::sync_with_stdio(false);
    cin>>n;
    for(int i=1;i<=n;i++){
        cin>>a[i].first;
        a[i].first=n-a[i].first;
        a[i].second=i;
    }
    sort(a+1,a+n+1);
    for(int l=1,r=0;l<=n;l=r+1){
        for(r=l;r<n&&a[r+1].first==a[r].first;++r);
