#include <bits/stdc++.h>
using namespace std;
const int MOD=998244353;
typedef long long ll;
ll fac[2333],rfac[2333];
ll qp(ll a,ll b)
{
	ll x=1; a%=MOD;
	while(b)
	{
		if(b&1) x=x*a%MOD;
		a=a*a%MOD; b>>=1;
	}
	return x;
}
int n,m,k;
int main()
{
	scanf("%d%d%d",&n,&m,&k);
	fac[0]=1;
	for(int i=1;i<=n;++i)
		fac[i]=fac[i-1]*i%MOD;
	rfac[n]=qp(fac[n],MOD-2);
	for(int i=n;i;--i)
		rfac[i-1]=rfac[i]*i%MOD;
	printf("%lld\n",m*qp(m-1,k)%MOD*fac[n-1]%MOD
	*rfac[k]%MOD*rfac[n-1-k]%MOD);
}

