int n,ss[10005],sn=0,q[333];
bool tf(int l,int r)
{
	cout<<"? "<<l<<" "<<r<<endl<<flush;
	cin>>ss[++sn];
	return (ss[sn]-ss[sn-1])&1;
}
int main()
{
	cin>>n>>ss[0]; q[n]=ss[0];
	for(int i=1;i<n;++i)
	{
		int j=i-n%2;
		if(j==0)
		{
			int t[2]={0,0},u=ss[sn];
			while(t[0]!=1||t[1]!=0)
				t[tf(2,n)]^=1;
			int v=ss[sn];
			q[i]=q[n]-(n-1-v+u)/2;
			while(t[0]||t[1])
				t[tf(2,n)]^=1;
		}
		else
		{
			int t[2]={0,0},u=ss[sn];
			while(t[0]!=1||t[1]!=0)
				t[(tf(j,i)^i)&1]^=1;
			int v=ss[sn];
